(50487, 957, 527, '<td valign="top">Nice and simple. Good framing.</td>', 'Nice and simple. Good framing.', '2002-04-26 16:03:00.000000', NULL, 1),
(50488, 957, 346, '<td valign="top">really beautiful shot. Love the colors.</td>', 'really beautiful shot. Love the colors.', '2002-04-27 07:20:00.000000', NULL, 1),
(50489, 957, 813, '<td valign="top">This could be improved with a composition that leads the eye to where the plants are breaking ground, therefore emphasizing transition.  Perhaps closer cropping and lower angle.</td>', 'This could be improved with a composition that leads the eye to where the plants are breaking ground, therefore emphasizing transition.  Perhaps closer cropping and lower angle.', '2002-04-27 11:58:00.000000', NULL, 1),
(50490, 957, 811, '<td valign="top">If you could have zoomed in on the flowers in front, I think it might have been more effective.  Great focus and clarity.</td>', 'If you could have zoomed in on the flowers in front, I think it might have been more effective.  Great focus and clarity.', '2002-04-27 19:48:00.000000', NULL, 1),
