(50503, 959, 772, '<td valign="top">With the help of the title and the tea label, I finally figured out what is going on in this photo.  I think this is a difficult and devious angle for photographing a glass of tea.</td>', 'With the help of the title and the tea label, I finally figured out what is going on in this photo.  I think this is a difficult and devious angle for photographing a glass of tea.', '2002-04-22 15:29:00.000000', NULL, 1),
(50504, 959, 933, '<td valign="top">Very unusual angle. Maybe a lighter base would have allowed for the discoloration of the water/tea to show through better.</td>', 'Very unusual angle. Maybe a lighter base would have allowed for the discoloration of the water/tea to show through better.', '2002-04-22 17:56:00.000000', NULL, 1),
