(50723, 991, 436, '<td valign="top">I like the infinity symbol in the chain and the depth of field</td>', 'I like the infinity symbol in the chain and the depth of field', '2002-04-24 10:55:00.000000', NULL, 1),
(50724, 991, 749, '<td valign="top">Good lateral thinking! I would prefer slightly more light and focus on the cross itself tho</td>', 'Good lateral thinking! I would prefer slightly more light and focus on the cross itself tho', '2002-04-24 14:09:00.000000', NULL, 1),
(50725, 991, 472, '<td valign="top">i really dig the composition and angle you used.<br/></td>', 'i really dig the composition and angle you used.', '2002-04-24 17:19:00.000000', NULL, 1),
(50726, 991, 131, '<td valign="top">Very Impressive</td>', 'Very Impressive', '2002-04-24 17:35:00.000000', NULL, 1),
(50727, 991, 570, '<td valign="top">just plain  l a m e</td>', 'just plain  l a m e', '2002-04-25 15:38:00.000000', NULL, 1),
(50728, 991, 75, '<td valign="top">awesome message :)</td>', 'awesome message :)', '2002-04-26 07:39:00.000000', NULL, 1),
(50729, 991, 527, '<td valign="top">It is an excellent picture but the transition is not evident. I know what it means to you but the meaning is internal. It still gets a good score because it is such an excellent photo.</td>', 'It is an excellent picture but the transition is not evident. I know what it means to you but the meaning is internal. It still gets a good score because it is such an excellent photo.', '2002-04-26 17:19:00.000000', NULL, 1),
(50730, 991, 346, '<td valign="top">really great shot. Love the composition, dof.</td>', 'really great shot. Love the composition, dof.', '2002-04-27 06:46:00.000000', NULL, 1),
(50731, 991, 811, '<td valign="top">A personal favorite and symbolic of a transition in my life. :-)  Technically speaking, if the angle was rotated more so the cross didn''t fade into the shadows, it would have been more of a focus item.  My eyes tend to follow the chain, as it is.  Nice picture.</td>', 'A personal favorite and symbolic of a transition in my life. :-)  Technically speaking, if the angle was rotated more so the cross didn''t fade into the shadows, it would have been more of a focus item.  My eyes tend to follow the chain, as it is.  Nice picture.', '2002-04-27 13:59:00.000000', NULL, 1),
(50732, 991, 1350, '<td valign="top">I love this pic...the infinity symbol really touches it off...this one captures me. Well done!</td>', 'I love this pic...the infinity symbol really touches it off...this one captures me. Well done!', '2002-04-27 17:32:00.000000', NULL, 1),
(50733, 991, 1290, '<td valign="top">What can I say - Jesus is Lord! Amen.</td>', 'What can I say - Jesus is Lord! Amen.', '2002-04-27 21:35:00.000000', NULL, 1),
(50734, 991, 869, '<td valign="top">Nice symbolism, lighting, focus...</td>', 'Nice symbolism, lighting, focus...', '2002-04-27 21:46:00.000000', NULL, 1),
(50735, 991, 2, '<td valign="top">Very cool composition, and excellent use of contrast and depth-of-field.</td>', 'Very cool composition, and excellent use of contrast and depth-of-field.', '2002-04-28 12:19:00.000000', NULL, 1),
(50736, 991, 245, '<td valign="top">dust! dust that surface! :)</td>', 'dust! dust that surface! :)', '2002-04-28 18:16:00.000000', NULL, 1),
(50737, 991, 637, '<td valign="top">What''s the transition?</td>', 'What''s the transition?', '2002-04-28 23:12:00.000000', NULL, 1),
