(50739, 991, 843, '<td valign="top">That''s smoke in the background but it''s hard to tell. I wish I had lit the cross better, as well as open the aperature a bit more to include more of the foreground in focus. And yes I did put the chain in an infinity symbol on purpose. I know my Bible!</td>', 'That''s smoke in the background but it''s hard to tell. I wish I had lit the cross better, as well as open the aperature a bit more to include more of the foreground in focus. And yes I did put the chain in an infinity symbol on purpose. I know my Bible!', '2002-04-29 21:43:00.000000', NULL, 0),
(50740, 991, 472, '<td valign="top">i''m not religious but i thought this was a great photo and should have ranked higher.  you should be very happy with it</td>', 'i''m not religious but i thought this was a great photo and should have ranked higher.  you should be very happy with it', '2002-05-02 08:40:00.000000', NULL, 0),
(50741, 996, 739, '<td valign="top">I submitted a similar picture, though mine was taken several minutes later to give the colors in the horizon more of a gradient from yellow down to red.  I like the framing effect by the two trees.  It really focuses my attention to the clouds and color of the sky.</td>', 'I submitted a similar picture, though mine was taken several minutes later to give the colors in the horizon more of a gradient from yellow down to red.  I like the framing effect by the two trees.  It really focuses my attention to the clouds and color of the sky.', '2002-04-22 02:13:00.000000', NULL, 1),
(50742, 996, 1040, '<td valign="top">Nice sunset....</td>', 'Nice sunset....', '2002-04-22 03:38:00.000000', NULL, 1),
(50743, 996, 441, '<td valign="top">good strong submission</td>', 'good strong submission', '2002-04-23 15:00:00.000000', NULL, 1),
(50744, 996, 933, '<td valign="top">Nicely framed sunset photo.</td>', 'Nicely framed sunset photo.', '2002-04-25 14:17:00.000000', NULL, 1),
(50745, 996, 656, '<td valign="top">bit too much dark frame.  Nice silohettes.</td>', 'bit too much dark frame.  Nice silohettes.', '2002-04-22 08:16:00.000000', NULL, 1),
(50746, 996, 1251, '<td valign="top">Very nice.</td>', 'Very nice.', '2002-04-22 08:49:00.000000', NULL, 1),
