(50750, 996, 661, '<td valign="top">Nice Color Tranisition.  One nit ... the yellow dot at the bottom.  To bad no photoshop allowed.</td>', 'Nice Color Tranisition.  One nit ... the yellow dot at the bottom.  To bad no photoshop allowed.', '2002-04-22 13:23:00.000000', NULL, 1),
(50751, 996, 641, '<td valign="top">really good shot</td>', 'really good shot', '2002-04-22 13:25:00.000000', NULL, 1),
