(50754, 996, 327, '<td valign="top">pretty sky, nice shot.</td>', 'pretty sky, nice shot.', '2002-04-22 15:26:00.000000', NULL, 1),
(50755, 996, 772, '<td valign="top">I like your sunset!  The silhouetted trees make this a very nice transition shot from day to night... good work!</td>', 'I like your sunset!  The silhouetted trees make this a very nice transition shot from day to night... good work!', '2002-04-22 17:05:00.000000', NULL, 1),
(50756, 996, 428, '<td valign="top">Beautiful!  Nice framing with the trees.   "Red sky at night sailor''s delight..."  Good shot!</td>', 'Beautiful!  Nice framing with the trees.   "Red sky at night sailor''s delight..."  Good shot!', '2002-04-22 17:42:00.000000', NULL, 1),
(50757, 996, 689, '<td valign="top">Nice colors</td>', 'Nice colors', '2002-04-22 20:11:00.000000', NULL, 1),
(50758, 996, 675, '<td valign="top">the picture looks tilted, sunsets are typical transition material</td>', 'the picture looks tilted, sunsets are typical transition material', '2002-04-22 21:37:00.000000', NULL, 1),
(50759, 996, 1, '<td valign="top">One of the better sunrise/sunet pictures, I like the bordering trees and the centered one as well.  I just wish the two bordering ones were more uniform.</td>', 'One of the better sunrise/sunet pictures, I like the bordering trees and the centered one as well.  I just wish the two bordering ones were more uniform.', '2002-04-23 14:01:00.000000', NULL, 1),
(50760, 996, 749, '<td valign="top">The colours are good, but the transition isn''t so clear - the colour gradient is being masked by the trees and cloud a bit too much</td>', 'The colours are good, but the transition isn''t so clear - the colour gradient is being masked by the trees and cloud a bit too much', '2002-04-24 13:37:00.000000', NULL, 1),
(50761, 996, 714, '<td valign="top">Beautiful!!</td>', 'Beautiful!!', '2002-04-24 18:03:00.000000', NULL, 1),
(50762, 996, 142, '<td valign="top">Well framed and attractive.</td>', 'Well framed and attractive.', '2002-04-26 06:33:00.000000', NULL, 1),
(50763, 996, 888, '<td valign="top">that came out really well</td>', 'that came out really well', '2002-04-27 16:09:00.000000', NULL, 1),
(50764, 996, 1070, '<td valign="top">wow. like it alot.  the silhouette of the trees frame the colourfull sky image beautifully.</td>', 'wow. like it alot.  the silhouette of the trees frame the colourfull sky image beautifully.', '2002-04-27 17:12:00.000000', NULL, 1),
(50765, 996, 1031, '<td valign="top">I like this -- maybe it''s similar to my style...nice detail considering the conditions and the file size limitations.</td>', 'I like this -- maybe it''s similar to my style...nice detail considering the conditions and the file size limitations.', '2002-04-27 18:34:00.000000', NULL, 1),
(50766, 996, 811, '<td valign="top">Nice colors, and hte trees frame the picture well.</td>', 'Nice colors, and hte trees frame the picture well.', '2002-04-27 21:01:00.000000', NULL, 1),
(50767, 996, 346, '<td valign="top">really great job framing the shot. Love the silhouette of the tree in the middle. nice colors also.</td>', 'really great job framing the shot. Love the silhouette of the tree in the middle. nice colors also.', '2002-04-28 07:18:00.000000', NULL, 1),
(50768, 996, 2, '<td valign="top">Excellent contrast and use of silhouette.</td>', 'Excellent contrast and use of silhouette.', '2002-04-28 12:27:00.000000', NULL, 1),
(50769, 996, 245, '<td valign="top">the black of the trees on each side could frame this really nicely, but it feels like it''s encroaching into the image a bit much, perhaps if this were framed horizontally to reduce the ratio of trees to sunset it might work better.</td>', 'the black of the trees on each side could frame this really nicely, but it feels like it''s encroaching into the image a bit much, perhaps if this were framed horizontally to reduce the ratio of trees to sunset it might work better.', '2002-04-28 18:06:00.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(50770, 997, 92, '<td valign="top">I REALLY like this capture. Great idea and the framing of shrubs just sets the thing off ! I do wish there was something on this side to show a real transition but no clue how that could be done any better. The view is beautiful:)</td>', 'I REALLY like this capture. Great idea and the framing of shrubs just sets the thing off ! I do wish there was something on this side to show a real transition but no clue how that could be done any better. The view is beautiful:)', '2002-04-22 01:29:00.000000', NULL, 1),
(50771, 997, 843, '<td valign="top">Would like to see it cropped on the sides.</td>', 'Would like to see it cropped on the sides.', '2002-04-22 03:25:00.000000', NULL, 1),
(50772, 997, 441, '<td valign="top">nice colourful shot</td>', 'nice colourful shot', '2002-04-23 14:52:00.000000', NULL, 1),
(50773, 997, 1175, '<td valign="top">Nice colors through the passageway.  I wonder if it would have been better suited for a vertically oriented photograph with the entry way taking up just a bit more of the picture.</td>', 'Nice colors through the passageway.  I wonder if it would have been better suited for a vertically oriented photograph with the entry way taking up just a bit more of the picture.', '2002-04-23 16:45:00.000000', NULL, 1),
(50774, 997, 1024, '<td valign="top">Almost like the Wizard of Oz...... changing from very dark to bright colors.  The only thing I might change would be a tighter crop.</td>', 'Almost like the Wizard of Oz...... changing from very dark to bright colors.  The only thing I might change would be a tighter crop.', '2002-04-22 08:33:00.000000', NULL, 1),
(50775, 997, 656, '<td valign="top">cool interpretation.  Like the light/dark contrast.</td>', 'cool interpretation.  Like the light/dark contrast.', '2002-04-22 08:42:00.000000', NULL, 1),
(50776, 997, 1, '<td valign="top">Nicely framed.  The sun shining in the garden and not on the bushes outside of the garden is a nice touch.</td>', 'Nicely framed.  The sun shining in the garden and not on the bushes outside of the garden is a nice touch.', '2002-04-22 08:52:00.000000', NULL, 1),
(50777, 997, 301, '<td valign="top">too much dark hedge here for my liking</td>', 'too much dark hedge here for my liking', '2002-04-22 11:09:00.000000', NULL, 1),
