(51377, 1036, 798, '<td valign="top">Nice picture but whats the transition?</td>', 'Nice picture but whats the transition?', '2002-04-22 15:09:00.000000', NULL, 1),
(51378, 1036, 459, '<td valign="top">I don''t get it.</td>', 'I don''t get it.', '2002-04-22 16:53:00.000000', NULL, 1),
(51379, 1036, 772, '<td valign="top">Is the transition being described here that the dozer is gonna tear down the trees?  If so, it''s an interesting transition.  This photo could have used a little different lighting situation possibly.  However, the ''blue'' does a nice job of accenting your theme of ''crying''.  Nice shot!</td>', 'Is the transition being described here that the dozer is gonna tear down the trees?  If so, it''s an interesting transition.  This photo could have used a little different lighting situation possibly.  However, the ''blue'' does a nice job of accenting your theme of ''crying''.  Nice shot!', '2002-04-22 20:24:00.000000', NULL, 1),
(51380, 1036, 675, '<td valign="top">i love the tint, don''t know about the transition, however<br/></td>', 'i love the tint, don''t know about the transition, however', '2002-04-22 21:12:00.000000', NULL, 1),
(51381, 1036, 428, '<td valign="top">lighting looks un-natural</td>', 'lighting looks un-natural', '2002-04-22 21:18:00.000000', NULL, 1),
(51382, 1036, 509, '<td valign="top">I''m not sure I like the blue overcast of this image...Also trying to get the transition, I''m guessing something to do with pollution, but I''m probably way off.  The focus is good on this though, very clear</td>', 'I''m not sure I like the blue overcast of this image...Also trying to get the transition, I''m guessing something to do with pollution, but I''m probably way off.  The focus is good on this though, very clear', '2002-04-22 21:25:00.000000', NULL, 1),
