(51576, 1048, 824, '<td valign="top">Very interesting. There is almost two transitions in this picture. The traffic light, and the tree. The left half seems to be taken during fall, and the right during spring. Nice!</td>', 'Very interesting. There is almost two transitions in this picture. The traffic light, and the tree. The left half seems to be taken during fall, and the right during spring. Nice!', '2002-04-22 01:22:00.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(51577, 1048, 739, '<td valign="top">Good shot, though the colors on the left and right are washed out by the direct sunlight.  You might try this same shot at a later time in the day.  I think it would yield a better overall shot.</td>', 'Good shot, though the colors on the left and right are washed out by the direct sunlight.  You might try this same shot at a later time in the day.  I think it would yield a better overall shot.', '2002-04-22 02:00:00.000000', NULL, 1),
(51578, 1048, 843, '<td valign="top">Could crop it tighter. Edges seem washed out.</td>', 'Could crop it tighter. Edges seem washed out.', '2002-04-22 03:50:00.000000', NULL, 1),
(51579, 1048, 441, '<td valign="top">nice shot, good contrast between traffic lights and misty trees</td>', 'nice shot, good contrast between traffic lights and misty trees', '2002-04-23 15:07:00.000000', NULL, 1),
(51580, 1048, 749, '<td valign="top">Great background to this - almost a transition in itself with the range of colours of leaves!</td>', 'Great background to this - almost a transition in itself with the range of colours of leaves!', '2002-04-25 14:11:00.000000', NULL, 1),
(51581, 1048, 656, '<td valign="top">nice attempt - too centrally framed though.</td>', 'nice attempt - too centrally framed though.', '2002-04-22 08:45:00.000000', NULL, 1),
(51582, 1048, 1024, '<td valign="top">Too bad you could not take this at a different time of day.  The background looks a little washed out.</td>', 'Too bad you could not take this at a different time of day.  The background looks a little washed out.', '2002-04-22 09:04:00.000000', NULL, 1),
(51583, 1048, 138, '<td valign="top">this traffic like is sooo awesome!</td>', 'this traffic like is sooo awesome!', '2002-04-22 09:19:00.000000', NULL, 1),
(51584, 1048, 798, '<td valign="top">I like the colors awesome picture</td>', 'I like the colors awesome picture', '2002-04-22 09:30:00.000000', NULL, 1),
