(51587, 1048, 1175, '<td valign="top">Cool Traffic light.  I love the background too, it contains more transition.  I would have prefered an angle a few feet back from where you were and I would have composed the light a bit more to the right so its off center and we can see more of those beautiful orange leaves.</td>', 'Cool Traffic light.  I love the background too, it contains more transition.  I would have prefered an angle a few feet back from where you were and I would have composed the light a bit more to the right so its off center and we can see more of those beautiful orange leaves.', '2002-04-22 13:21:00.000000', NULL, 1),
(51588, 1048, 641, '<td valign="top">I like the angle and the background foliage. But it looks a little hazy..</td>', 'I like the angle and the background foliage. But it looks a little hazy..', '2002-04-22 13:40:00.000000', NULL, 1),
(51589, 1048, 1211, '<td valign="top">This seems a common theme, but it is really done well with the rich colors of the tree on the left of the signal and green to the right.  Nice photo.</td>', 'This seems a common theme, but it is really done well with the rich colors of the tree on the left of the signal and green to the right.  Nice photo.', '2002-04-22 15:21:00.000000', NULL, 1),
(51590, 1048, 117, '<td valign="top">was it fall last week, nice shot anyway</td>', 'was it fall last week, nice shot anyway', '2002-04-22 17:44:00.000000', NULL, 1),
(51591, 1048, 203, '<td valign="top">Water drop anyone?</td>', 'Water drop anyone?', '2002-04-22 17:46:00.000000', NULL, 1),
(51592, 1048, 933, '<td valign="top">My eye is actually drawn away from the subject to the beautiful trees behind.</td>', 'My eye is actually drawn away from the subject to the beautiful trees behind.', '2002-04-22 17:49:00.000000', NULL, 1),
(51593, 1048, 554, '<td valign="top">nice pair   best of the stoplight pics</td>', 'nice pair   best of the stoplight pics', '2002-04-22 19:56:00.000000', NULL, 1),
(51594, 1048, 772, '<td valign="top">Good transition... Looks like the sun was working against you in this shot... The brightness is a little hig on the right and on the left.  If your camera has the capability of using a filter on the lens, a polarizer helps trememdously in situations like this...</td>', 'Good transition... Looks like the sun was working against you in this shot... The brightness is a little hig on the right and on the left.  If your camera has the capability of using a filter on the lens, a polarizer helps trememdously in situations like this...', '2002-04-22 20:56:00.000000', NULL, 1),
(51595, 1048, 675, '<td valign="top">another yellow stoplight, not that there''s anything wrong with that</td>', 'another yellow stoplight, not that there''s anything wrong with that', '2002-04-22 22:12:00.000000', NULL, 1),
(51596, 1048, 113, '<td valign="top">Very cool, color matching is great between the two.  Contrast should help with the trees white fade look.</td>', 'Very cool, color matching is great between the two.  Contrast should help with the trees white fade look.', '2002-04-23 05:47:00.000000', NULL, 1),
(51597, 1048, 156, '<td valign="top">cool! spring here, autumn where you are -- i like the double transition, altho i think i''d prefer the light to be off to one side instead of centered, it''s nicely done!</td>', 'cool! spring here, autumn where you are -- i like the double transition, altho i think i''d prefer the light to be off to one side instead of centered, it''s nicely done!', '2002-04-23 10:18:00.000000', NULL, 1),
(51598, 1048, 1, '<td valign="top">The background is very hazy which makes the image seem over exposed.  A different time of day or quicker shutter speed could remedy this.</td>', 'The background is very hazy which makes the image seem over exposed.  A different time of day or quicker shutter speed could remedy this.', '2002-04-23 11:20:00.000000', NULL, 1),
(51599, 1048, 1135, '<td valign="top">How did you get fall color in April? Are you south of the equator?</td>', 'How did you get fall color in April? Are you south of the equator?', '2002-04-23 16:54:00.000000', NULL, 1),
