(51622, 1051, 138, '<td valign="top">the title is the only transition</td>', 'the title is the only transition', '2002-04-22 09:09:00.000000', NULL, 1),
(51623, 1051, 2, '<td valign="top">I think maybe you should have shot this from further away -- with a field of those flower-marked gravestones setting the atmosphere more than the tent itself.  Also, slightly off center to the left.</td>', 'I think maybe you should have shot this from further away -- with a field of those flower-marked gravestones setting the atmosphere more than the tent itself.  Also, slightly off center to the left.', '2002-04-22 11:04:00.000000', NULL, 1),
