(51639, 1051, 346, '<td valign="top">this shot is really nice, I jsut wish the image had been just a little sharper.</td>', 'this shot is really nice, I jsut wish the image had been just a little sharper.', '2002-04-25 12:59:00.000000', NULL, 1),
