(51679, 1052, 1020, '<td valign="top">Way to catch it all...<br/>Light to dark, old to new!!!<br/>Good tones also!!!</td>', 'Way to catch it all...Light to dark, old to new!!!Good tones also!!!', '2002-04-27 01:05:00.000000', NULL, 1),
