(51709, 1054, 549, '<td valign="top">I really like this angle. This would be a great shot for "the ground up" challenge. I''m upgrading this to a 10.</td>', 'I really like this angle. This would be a great shot for "the ground up" challenge. I''m upgrading this to a 10.', '2002-04-24 09:07:00.000000', NULL, 1),
(51710, 1054, 428, '<td valign="top">I think this would have been better without the grass in the front. I would have liked to have seen the actual words on the stone</td>', 'I think this would have been better without the grass in the front. I would have liked to have seen the actual words on the stone', '2002-04-24 15:39:00.000000', NULL, 1),
