(51964, 1106, 1290, '<td valign="top">Too much sky, not enough of the fire - coming from Australia I think I am conditioned to seeing the spectacular photos of the dreadful fires we have here!</td>', 'Too much sky, not enough of the fire - coming from Australia I think I am conditioned to seeing the spectacular photos of the dreadful fires we have here!', '2002-04-27 21:40:00.000000', NULL, 1),
(51965, 1106, 889, '<td valign="top">beautiful shot.</td>', 'beautiful shot.', '2002-04-28 23:19:00.000000', NULL, 1),
(51966, 1106, 637, '<td valign="top">Guess I get it, but the picture leaves me wanting something more.</td>', 'Guess I get it, but the picture leaves me wanting something more.', '2002-04-28 23:25:00.000000', NULL, 1),
(51967, 1106, 1019, '<td valign="top">I was trying to show the transition in two ways  the first and most obvious the effect of the fire on the land the transition from solid to smoke but also the transition from clear blue sky to dirty brown smudgy air.I took the shot at sunset to get light on the smoke and also to make it a more abstract landscape with solid blocks of colour and not much detail.</td>', 'I was trying to show the transition in two ways  the first and most obvious the effect of the fire on the land the transition from solid to smoke but also the transition from clear blue sky to dirty brown smudgy air.I took the shot at sunset to get light on the smoke and also to make it a more abstract landscape with solid blocks of colour and not much detail.', '2002-04-29 01:09:00.000000', NULL, 0),
(51968, 1107, 739, '<td valign="top">It wasn''t obvious at first, but it is quite a clever composition.</td>', 'It wasn''t obvious at first, but it is quite a clever composition.', '2002-04-22 02:04:00.000000', NULL, 1),
(51969, 1107, 330, '<td valign="top">I like the way one person is in shadow and the other person is in the light. Good transition.</td>', 'I like the way one person is in shadow and the other person is in the light. Good transition.', '2002-04-22 07:02:00.000000', NULL, 1),
(51970, 1107, 656, '<td valign="top">nicely balanced with one in shadow and one in light.  Good transition shot,  though I don''t like the plastic. Well interpreted result - was it ''posed'' or candid ?</td>', 'nicely balanced with one in shadow and one in light.  Good transition shot,  though I don''t like the plastic. Well interpreted result - was it ''posed'' or candid ?', '2002-04-22 08:37:00.000000', NULL, 1),
(51971, 1107, 1024, '<td valign="top">Nice use of light and shadows.</td>', 'Nice use of light and shadows.', '2002-04-22 08:45:00.000000', NULL, 1),
(51972, 1107, 1, '<td valign="top">Transition is clear, but a bit of a boring subject.</td>', 'Transition is clear, but a bit of a boring subject.', '2002-04-22 09:14:00.000000', NULL, 1),
(51973, 1107, 1019, '<td valign="top">Superb contrast beautifully captured</td>', 'Superb contrast beautifully captured', '2002-04-22 09:59:00.000000', NULL, 1),
(51974, 1107, 878, '<td valign="top">Interesting shot</td>', 'Interesting shot', '2002-04-22 10:12:00.000000', NULL, 1),
