(52595, 1127, 888, '<td valign="top">Transition??</td>', 'Transition??', '2002-04-28 08:59:00.000000', NULL, 1),
(52596, 1127, 245, '<td valign="top">i wonder if people will react as strongly to this if they don''t smoke pot! technically, the sky is a bit blown out, and the contrast could use a bump to make the image a bit more punchy, it has the bluey cast of a snapshot. it made me take my first hit of the day anyway, immediately reproducing your transition. :)</td>', 'i wonder if people will react as strongly to this if they don''t smoke pot! technically, the sky is a bit blown out, and the contrast could use a bump to make the image a bit more punchy, it has the bluey cast of a snapshot. it made me take my first hit of the day anyway, immediately reproducing your transition. :)', '2002-04-28 18:57:00.000000', NULL, 1),
(52597, 1127, 637, '<td valign="top">Don''t see how this is a transition... its a handoff.</td>', 'Don''t see how this is a transition... its a handoff.', '2002-04-28 23:26:00.000000', NULL, 1),
