(52740, 1132, 637, '<td valign="top">What a cute little baby!  Nice transition.</td>', 'What a cute little baby!  Nice transition.', '2002-04-28 23:33:00.000000', NULL, 1),
(52741, 1133, 933, '<td valign="top">Interesting lighting &amp; interpretation of the challenge!</td>', 'Interesting lighting & interpretation of the challenge!', '2002-04-25 13:26:00.000000', NULL, 1),
(52742, 1133, 138, '<td valign="top">this was a good idea.. prolly would have been a better shot with real people</td>', 'this was a good idea.. prolly would have been a better shot with real people', '2002-04-22 08:59:00.000000', NULL, 1),
(52743, 1133, 885, '<td valign="top">well exposed, good highlight and shadow detail</td>', 'well exposed, good highlight and shadow detail', '2002-04-22 10:10:00.000000', NULL, 1),
(52744, 1133, 656, '<td valign="top">shadow under the face is really harsh - some fill flash or a reflector could have really helped.  well composed although you slightly clipped the lower arm.  I find very slight crops annoying, but major ones are okay.</td>', 'shadow under the face is really harsh - some fill flash or a reflector could have really helped.  well composed although you slightly clipped the lower arm.  I find very slight crops annoying, but major ones are okay.', '2002-04-22 10:33:00.000000', NULL, 1),
(52745, 1133, 641, '<td valign="top">good shot.. and good angle.</td>', 'good shot.. and good angle.', '2002-04-22 13:43:00.000000', NULL, 1),
(52746, 1133, 798, '<td valign="top">MMMM good</td>', 'MMMM good', '2002-04-22 13:55:00.000000', NULL, 1),
(52747, 1133, 1064, '<td valign="top">i like it. not too fond of the shadows, but it''s probably unavoidable.</td>', 'i like it. not too fond of the shadows, but it''s probably unavoidable.', '2002-04-22 14:42:00.000000', NULL, 1),
(52748, 1133, 259, '<td valign="top">i really like this photo, and the angle is what makes the picture.</td>', 'i really like this photo, and the angle is what makes the picture.', '2002-04-22 15:12:00.000000', NULL, 1),
(52749, 1133, 387, '<td valign="top">creative, um, subject. good detail, contrast and composition</td>', 'creative, um, subject. good detail, contrast and composition', '2002-04-22 17:15:00.000000', NULL, 1),
(52750, 1133, 346, '<td valign="top">I can''t tell if it was a B&amp;W or not. really nice contrast.</td>', 'I can''t tell if it was a B&W or not. really nice contrast.', '2002-04-22 20:36:00.000000', NULL, 1),
(52751, 1133, 772, '<td valign="top">Nice scuplture!</td>', 'Nice scuplture!', '2002-04-22 21:38:00.000000', NULL, 1),
(52752, 1133, 675, '<td valign="top">it''s a statue</td>', 'it''s a statue', '2002-04-22 23:20:00.000000', NULL, 1),
(52753, 1133, 965, '<td valign="top">Great idea for the theme, and especially like the angle of the shot, looking down as opposed to the normal head on shots. Only slight down side is the shadow on the face, but still a great picture</td>', 'Great idea for the theme, and especially like the angle of the shot, looking down as opposed to the normal head on shots. Only slight down side is the shadow on the face, but still a great picture', '2002-04-23 04:52:00.000000', NULL, 1),
(52754, 1133, 107, '<td valign="top">fantastic shot</td>', 'fantastic shot', '2002-04-23 08:12:00.000000', NULL, 1),
(52755, 1133, 1244, '<td valign="top">This is a great photo from a interesting angle, but with me statue does not conjure images of change or transition.  The theme of the statue is certainly appropriate, but I guess not the medium of the statue.  I hope that made sense.</td>', 'This is a great photo from a interesting angle, but with me statue does not conjure images of change or transition.  The theme of the statue is certainly appropriate, but I guess not the medium of the statue.  I hope that made sense.', '2002-04-23 09:56:00.000000', NULL, 1),
(52756, 1133, 441, '<td valign="top">good shot of a superb sculpture</td>', 'good shot of a superb sculpture', '2002-04-23 11:34:00.000000', NULL, 1),
(52757, 1133, 1, '<td valign="top">I don''t like the shadow on her face.  A different time of day would fix that right up.  Otherwise a nice angle that draws you right into the subject.</td>', 'I don''t like the shadow on her face.  A different time of day would fix that right up.  Otherwise a nice angle that draws you right into the subject.', '2002-04-23 11:42:00.000000', NULL, 1),
(52758, 1133, 156, '<td valign="top">from your title i''m presuming the transition is that of infant to adult but the way it''s depicted puts me more in mind of the breast''s transition from playtoy to feeding vessel...</td>', 'from your title i''m presuming the transition is that of infant to adult but the way it''s depicted puts me more in mind of the breast''s transition from playtoy to feeding vessel...', '2002-04-23 13:37:00.000000', NULL, 1),
(52759, 1133, 357, '<td valign="top">Growth, yet inanimate.  Not much hope for transition here...</td>', 'Growth, yet inanimate.  Not much hope for transition here...', '2002-04-23 18:42:00.000000', NULL, 1),
(52760, 1133, 352, '<td valign="top">Very cool lighting and shadows being thrown here...</td>', 'Very cool lighting and shadows being thrown here...', '2002-04-23 21:13:00.000000', NULL, 1),
(52761, 1133, 918, '<td valign="top">Someone else''s art. Good composition.</td>', 'Someone else''s art. Good composition.', '2002-04-25 06:41:00.000000', NULL, 1),
(52762, 1133, 2, '<td valign="top">As prominent as the shadow is in the composition of this photo, I can''t figure out how it adds to the ultimate subject of the photo, your transition.</td>', 'As prominent as the shadow is in the composition of this photo, I can''t figure out how it adds to the ultimate subject of the photo, your transition.', '2002-04-25 23:41:00.000000', NULL, 1),
(52763, 1133, 142, '<td valign="top">Lovely interpretation.  I like the use of black and white and your lighting is good.</td>', 'Lovely interpretation.  I like the use of black and white and your lighting is good.', '2002-04-26 06:28:00.000000', NULL, 1),
(52764, 1133, 1336, '<td valign="top">the shadow detracts from the photograph.  also, i think there''s a rule about sculpture and artwork not being allowed as the only thing in a submitted picture.</td>', 'the shadow detracts from the photograph.  also, i think there''s a rule about sculpture and artwork not being allowed as the only thing in a submitted picture.', '2002-04-26 20:31:00.000000', NULL, 1),
(52765, 1133, 472, '<td valign="top">beautiful.  tone, texture, light.  love it.  took a little while to grow on me, but i rated it high</td>', 'beautiful.  tone, texture, light.  love it.  took a little while to grow on me, but i rated it high', '2002-04-26 21:43:00.000000', NULL, 1),
(52766, 1133, 714, '<td valign="top">One of the slowest of all transitions, but the most precious of all.  Life.  Great picture.  I like the lighting.</td>', 'One of the slowest of all transitions, but the most precious of all.  Life.  Great picture.  I like the lighting.', '2002-04-26 22:23:00.000000', NULL, 1),
(52767, 1133, 811, '<td valign="top">nice shot.  on the thumbnail, I thought it was a real person. :-)</td>', 'nice shot.  on the thumbnail, I thought it was a real person. :-)', '2002-04-27 14:04:00.000000', NULL, 1),
(52768, 1133, 1070, '<td valign="top">This statue shows fantastic transition, and you''ve captured it from a great angle.</td>', 'This statue shows fantastic transition, and you''ve captured it from a great angle.', '2002-04-27 18:08:00.000000', NULL, 1),
(52769, 1133, 888, '<td valign="top">ah nudity, shame its a statue!!!<br/>I love the light and shadow on this</td>', 'ah nudity, shame its a statue!!!I love the light and shadow on this', '2002-04-28 09:28:00.000000', NULL, 1),
(52770, 1133, 245, '<td valign="top">interesting angle, but the framing feels just a smidge too tight, the slightest gaps between her elbow, the baby and the edge might help.</td>', 'interesting angle, but the framing feels just a smidge too tight, the slightest gaps between her elbow, the baby and the edge might help.', '2002-04-28 18:18:00.000000', NULL, 1),
(52771, 1134, 739, '<td valign="top">A transition from flying to not-flying? Okay, I can go for that.</td>', 'A transition from flying to not-flying? Okay, I can go for that.', '2002-04-22 01:30:00.000000', NULL, 1),
(52772, 1134, 1, '<td valign="top">The shot is a bit grainy.  Otherwise It might''ve been nice for Stopped-Motion, not Transitions.</td>', 'The shot is a bit grainy.  Otherwise It might''ve been nice for Stopped-Motion, not Transitions.', '2002-04-22 07:50:00.000000', NULL, 1),
(52773, 1134, 798, '<td valign="top">What''s the transition? Oh I got it. Good job!</td>', 'What''s the transition? Oh I got it. Good job!', '2002-04-22 09:19:00.000000', NULL, 1),
(52774, 1134, 656, '<td valign="top">air to ground transition ?  good stop motion shot :)</td>', 'air to ground transition ?  good stop motion shot :)', '2002-04-22 10:55:00.000000', NULL, 1),
(52775, 1134, 509, '<td valign="top">This picture is suffering from a lot of jpeg compression artifacts.  Transition from ground to sky though is interesting</td>', 'This picture is suffering from a lot of jpeg compression artifacts.  Transition from ground to sky though is interesting', '2002-04-22 11:35:00.000000', NULL, 1),
(52776, 1134, 641, '<td valign="top">good idea.. kinda grainy though</td>', 'good idea.. kinda grainy though', '2002-04-22 13:26:00.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(52777, 1134, 1175, '<td valign="top">Without a title you can''t really tell if this is landing or taking off.  Image is grainy.</td>', 'Without a title you can''t really tell if this is landing or taking off.  Image is grainy.', '2002-04-22 14:27:00.000000', NULL, 1),
(52778, 1134, 203, '<td valign="top">The very shot I wanted to take but could not get close enough.  Well done getting through security.</td>', 'The very shot I wanted to take but could not get close enough.  Well done getting through security.', '2002-04-22 17:21:00.000000', NULL, 1),
(52779, 1134, 117, '<td valign="top">i hope that was a landing</td>', 'i hope that was a landing', '2002-04-22 17:47:00.000000', NULL, 1),
(52780, 1134, 933, '<td valign="top">Image is a bit grainy and out of focus. Subject is not too compelling.</td>', 'Image is a bit grainy and out of focus. Subject is not too compelling.', '2002-04-22 17:53:00.000000', NULL, 1),
(52781, 1134, 428, '<td valign="top">good shot!</td>', 'good shot!', '2002-04-22 21:05:00.000000', NULL, 1),
(52782, 1134, 772, '<td valign="top">This is a nice transition photo.  I like it.  The photo quality is suffering because of the small area cropped out of the larger photo, i think... I could be wrong but there is some amount of image quality degradation here.</td>', 'This is a nice transition photo.  I like it.  The photo quality is suffering because of the small area cropped out of the larger photo, i think... I could be wrong but there is some amount of image quality degradation here.', '2002-04-22 21:06:00.000000', NULL, 1),
(52783, 1134, 675, '<td valign="top">is this a scene from castaway?</td>', 'is this a scene from castaway?', '2002-04-22 23:18:00.000000', NULL, 1),
(52784, 1134, 156, '<td valign="top">great idea and capture!</td>', 'great idea and capture!', '2002-04-23 09:01:00.000000', NULL, 1),
(52785, 1134, 749, '<td valign="top">Good transition, great timing</td>', 'Good transition, great timing', '2002-04-24 14:32:00.000000', NULL, 1),
(52786, 1134, 714, '<td valign="top">So what is the transition here, from FedEx to UPS.  :)  You know UPS is the better of the two.  LOL   My husband works for UPS.  Nice picture.  I wonder how fast he is going.</td>', 'So what is the transition here, from FedEx to UPS.  :)  You know UPS is the better of the two.  LOL   My husband works for UPS.  Nice picture.  I wonder how fast he is going.', '2002-04-24 21:09:00.000000', NULL, 1),
(52787, 1134, 811, '<td valign="top">Good idea, framing it further to the right so that it would have looked like the plane had somewhere to go may have made it better.</td>', 'Good idea, framing it further to the right so that it would have looked like the plane had somewhere to go may have made it better.', '2002-04-26 10:08:00.000000', NULL, 1),
(52788, 1134, 441, '<td valign="top">airbeast to landbeast? thought you had overcompressed this shown by the degradation in detail, have you over-sharpened this image - loads of ''moire'' around aircraft body?</td>', 'airbeast to landbeast? thought you had overcompressed this shown by the degradation in detail, have you over-sharpened this image - loads of ''moire'' around aircraft body?', '2002-04-26 16:30:00.000000', NULL, 1),
(52789, 1134, 587, '<td valign="top">Would have liked to have been able to see this up closer, but if you aren''t driving the plane these days forget about it! ;) This would have made a great ''stopped motion''! good job.</td>', 'Would have liked to have been able to see this up closer, but if you aren''t driving the plane these days forget about it! ;) This would have made a great ''stopped motion''! good job.', '2002-04-27 21:55:00.000000', NULL, 1),
(52790, 1134, 889, '<td valign="top">Replies: <br/>The image was a plane transitioning from flying to landing. You dont get smoke off the wheels when taking off unless there is something very wrong. The distortion under the wings was caused by the hot exaust gases from the engines.<br/>The image was a cropped down version but the main reason for the artifacts was over-sharpening. The area I cropped was 800x534 and then resized to 640x427.<br/>The view of the original is [url=//www.pbase.com/image/1850152]here[/name][/link.].   (//www.pbase.com/image/1850152)<br/><br/>I was not inside the fence I was siting on top of my van which is why you dont see the fence. The Roadway is very close to the Runway however the original better shows the true distance.<br/>A 6x optical lens was used. The only reason I didnt go farther to the left was that I wanted to include more wheel smoke.</td>', 'Replies: The image was a plane transitioning from flying to landing. You dont get smoke off the wheels when taking off unless there is something very wrong. The distortion under the wings was caused by the hot exaust gases from the engines.The image was a cropped down version but the main reason for the artifacts was over-sharpening. The area I cropped was 800x534 and then resized to 640x427.The view of the original is [url=//www.pbase.com/image/1850152]here[/name][/link.].   (//www.pbase.com/image/1850152)I was not inside the fence I was siting on top of my van which is why you dont see the fence. The Roadway is very close to the Runway however the original better shows the true distance.A 6x optical lens was used. The only reason I didnt go farther to the left was that I wanted to include more wheel smoke.', '2002-04-29 02:07:00.000000', NULL, 0),
(52791, 1134, 889, '<td valign="top"><br/>This is a link to the <a href="//www.pbase.com/image/1850152/large" rel="nofollow" target="_blank">orriginal</a> photo that created the submission.<br/></td>', 'This is a link to the orriginal photo that created the submission.', '2002-05-06 14:56:00.000000', NULL, 0),
(52792, 1135, 92, '<td valign="top">Great capture !</td>', 'Great capture !', '2002-04-22 01:39:00.000000', NULL, 1),
(52793, 1135, 843, '<td valign="top">Would have been nice to see the traffic light in more detail and maybe not centered so much. Like the idea though.</td>', 'Would have been nice to see the traffic light in more detail and maybe not centered so much. Like the idea though.', '2002-04-22 02:55:00.000000', NULL, 1),
(52794, 1135, 107, '<td valign="top">I would have liked the actual traffic light a bit brighter.  It''s a good shot.  I like the moon in the background.</td>', 'I would have liked the actual traffic light a bit brighter.  It''s a good shot.  I like the moon in the background.', '2002-04-22 06:05:00.000000', NULL, 1),
(52795, 1135, 789, '<td valign="top">Yoooo! Cool pic.</td>', 'Yoooo! Cool pic.', '2002-04-23 14:37:00.000000', NULL, 1),
(52796, 1135, 441, '<td valign="top">good exposure</td>', 'good exposure', '2002-04-23 15:56:00.000000', NULL, 1),
(52797, 1135, 749, '<td valign="top">Two transitions? You''re really hedging your bets :o) Nicely done tho</td>', 'Two transitions? You''re really hedging your bets :o) Nicely done tho', '2002-04-25 13:45:00.000000', NULL, 1),
(52798, 1135, 1024, '<td valign="top">Nice interpretation..... maybe a tighter crop would have been more effective though.</td>', 'Nice interpretation..... maybe a tighter crop would have been more effective though.', '2002-04-22 08:49:00.000000', NULL, 1),
(52799, 1135, 138, '<td valign="top">the picture is a tad too dark, but nice idea</td>', 'the picture is a tad too dark, but nice idea', '2002-04-22 09:14:00.000000', NULL, 1),
(52800, 1135, 1154, '<td valign="top">Capturing ManMade transitions and Natures transitions<br/>was brilliant!</td>', 'Capturing ManMade transitions and Natures transitionswas brilliant!', '2002-04-22 09:22:00.000000', NULL, 1),
(52801, 1135, 1155, '<td valign="top">One of the only true transistions i have seen in this contest.  Good job.</td>', 'One of the only true transistions i have seen in this contest.  Good job.', '2002-04-22 09:57:00.000000', NULL, 1),
(52802, 1135, 656, '<td valign="top">personally I think the moon detracts from this.  An off centered framing might have been a bit stronger too, or holding the camera vertically to get more in the frame.</td>', 'personally I think the moon detracts from this.  An off centered framing might have been a bit stronger too, or holding the camera vertically to get more in the frame.', '2002-04-22 10:06:00.000000', NULL, 1),
(52803, 1135, 641, '<td valign="top">great catch</td>', 'great catch', '2002-04-22 11:14:00.000000', NULL, 1),
(52804, 1135, 1175, '<td valign="top">Too dark.  Good idea though. :)</td>', 'Too dark.  Good idea though. :)', '2002-04-22 14:23:00.000000', NULL, 1),
(52805, 1135, 933, '<td valign="top">A little dark.  The subject is not terribly compelling.</td>', 'A little dark.  The subject is not terribly compelling.', '2002-04-22 15:31:00.000000', NULL, 1),
(52806, 1135, 203, '<td valign="top">Much better than the other yellow light.  But were there are two I bet there are more.</td>', 'Much better than the other yellow light.  But were there are two I bet there are more.', '2002-04-22 17:37:00.000000', NULL, 1),
(52807, 1135, 772, '<td valign="top">Did you fire your flash on this shot?  A little light on the stoplight casing would have been nice in this shot... I also like the moon being in teh photo... nice touch!</td>', 'Did you fire your flash on this shot?  A little light on the stoplight casing would have been nice in this shot... I also like the moon being in teh photo... nice touch!', '2002-04-22 21:02:00.000000', NULL, 1),
(52808, 1135, 675, '<td valign="top">good idea, very hard to execute by the looks of this picture</td>', 'good idea, very hard to execute by the looks of this picture', '2002-04-22 22:23:00.000000', NULL, 1),
(52809, 1135, 878, '<td valign="top">The shot is a bit too dark, this shot at dusk with a slightly different angle may produce a better effect. <br/><br/></td>', 'The shot is a bit too dark, this shot at dusk with a slightly different angle may produce a better effect. ', '2002-04-23 10:18:00.000000', NULL, 1),
(52810, 1135, 1, '<td valign="top">The shot would''ve been 10x as strong had you a green stop light in this shot (however that is likely impossible to frame).  I like how this stop light shot actually shows both stages (caution and stop).  It''s the best of the stop light shots.</td>', 'The shot would''ve been 10x as strong had you a green stop light in this shot (however that is likely impossible to frame).  I like how this stop light shot actually shows both stages (caution and stop).  It''s the best of the stop light shots.', '2002-04-23 11:45:00.000000', NULL, 1),
(52811, 1135, 715, '<td valign="top">Just too bad there isn''t a visible green light on the right.</td>', 'Just too bad there isn''t a visible green light on the right.', '2002-04-23 13:28:00.000000', NULL, 1),
(52812, 1135, 472, '<td valign="top">nice coincidental catch!</td>', 'nice coincidental catch!', '2002-04-24 08:31:00.000000', NULL, 1),
(52813, 1135, 889, '<td valign="top">Nice double trasition, the light and the moon.</td>', 'Nice double trasition, the light and the moon.', '2002-04-24 12:30:00.000000', NULL, 1),
(52814, 1135, 245, '<td valign="top">that''s wanes. :)</td>', 'that''s wanes. :)', '2002-04-24 13:43:00.000000', NULL, 1),
(52815, 1135, 509, '<td valign="top">The darkness accentuates the bright colors of the lights, but it doesn''t do much for the detail of the shot.  Not much to look at here, (I am looking at it without any glare on my screen, still hard to see much else in the picture).  Also, the moon (I think that is what it is) to the right distrats from the image.  Maybe if you had been able to take a different angle, in which it would be in say the top right corner, it would be better.</td>', 'The darkness accentuates the bright colors of the lights, but it doesn''t do much for the detail of the shot.  Not much to look at here, (I am looking at it without any glare on my screen, still hard to see much else in the picture).  Also, the moon (I think that is what it is) to the right distrats from the image.  Maybe if you had been able to take a different angle, in which it would be in say the top right corner, it would be better.', '2002-04-25 12:12:00.000000', NULL, 1),
(52816, 1135, 1191, '<td valign="top">This is my fave traffic light shot, brilliant.</td>', 'This is my fave traffic light shot, brilliant.', '2002-04-25 18:15:00.000000', NULL, 1),
(52817, 1135, 527, '<td valign="top">I think you need to ask yourself, would you take this picture if there were no contest? I want to be nice I just think this is taken only to meet the challenge.</td>', 'I think you need to ask yourself, would you take this picture if there were no contest? I want to be nice I just think this is taken only to meet the challenge.', '2002-04-26 18:24:00.000000', NULL, 1),
(52818, 1135, 1336, '<td valign="top">ah, a more creative traffic light photo.  the moon in the background is a nice touch - i also like it that both the red and yellow are in the picture.</td>', 'ah, a more creative traffic light photo.  the moon in the background is a nice touch - i also like it that both the red and yellow are in the picture.', '2002-04-26 20:44:00.000000', NULL, 1),
(52819, 1135, 811, '<td valign="top">neat shot, didn''t see the moon at first.  Nice idea</td>', 'neat shot, didn''t see the moon at first.  Nice idea', '2002-04-27 14:07:00.000000', NULL, 1),
(52820, 1135, 27, '<td valign="top">Although the compsition has an accidental feel, I''m AMAZED at the exposure balance you were able to achieve.  Quite impressive.</td>', 'Although the compsition has an accidental feel, I''m AMAZED at the exposure balance you were able to achieve.  Quite impressive.', '2002-04-27 15:26:00.000000', NULL, 1),
(52821, 1135, 888, '<td valign="top">I like the idea of trying to get the moon in but I think the moon just looks out of place</td>', 'I like the idea of trying to get the moon in but I think the moon just looks out of place', '2002-04-28 08:50:00.000000', NULL, 1),
(52822, 1135, 637, '<td valign="top">And they''re all lined up...</td>', 'And they''re all lined up...', '2002-04-28 23:18:00.000000', NULL, 1),
(52823, 1136, 441, '<td valign="top">good record shot</td>', 'good record shot', '2002-04-23 15:04:00.000000', NULL, 1),
(52824, 1136, 749, '<td valign="top">I think your transition is supposed to be from use to disuse/museum piece, but it took quite a bit of thought</td>', 'I think your transition is supposed to be from use to disuse/museum piece, but it took quite a bit of thought', '2002-04-25 14:01:00.000000', NULL, 1),
(52825, 1136, 656, '<td valign="top">not sure I really get the transition here - I can see the old, where''s the new ?  Just the fact that the railings are around it ?   The sky detracts from this - nothing in it - too white/grey.</td>', 'not sure I really get the transition here - I can see the old, where''s the new ?  Just the fact that the railings are around it ?   The sky detracts from this - nothing in it - too white/grey.', '2002-04-22 08:17:00.000000', NULL, 1),
(52826, 1136, 138, '<td valign="top">i dont get the transition</td>', 'i dont get the transition', '2002-04-22 09:05:00.000000', NULL, 1),
(52827, 1136, 1024, '<td valign="top">I wish there was more detail in the foreground.</td>', 'I wish there was more detail in the foreground.', '2002-04-22 09:21:00.000000', NULL, 1),
(52828, 1136, 641, '<td valign="top">what a beautiful and nostalgic shot.</td>', 'what a beautiful and nostalgic shot.', '2002-04-22 13:41:00.000000', NULL, 1),
(52829, 1136, 798, '<td valign="top">good train picture but whats the transition?</td>', 'good train picture but whats the transition?', '2002-04-22 13:53:00.000000', NULL, 1),
