(52977, 1141, 205, '<td valign="top">Very nice depth of field</td>', 'Very nice depth of field', '2002-04-23 02:37:00.000000', NULL, 1),
(52978, 1141, 965, '<td valign="top">Interesting idea for a picture. Works really well in black and white.</td>', 'Interesting idea for a picture. Works really well in black and white.', '2002-04-23 07:23:00.000000', NULL, 1),
(52979, 1141, 1244, '<td valign="top">I know this might sound strange, but the two hands don''t seem... "intimate" enough?  I think I would prefer to see both of their hands like in a real wedding ceremony.</td>', 'I know this might sound strange, but the two hands don''t seem... "intimate" enough?  I think I would prefer to see both of their hands like in a real wedding ceremony.', '2002-04-23 09:54:00.000000', NULL, 1),
