(53703, 1168, 245, '<td valign="top">the framing seems a little odd, I would have liked to see more of the tree in the foreground, pulling back from the scene a bit and letting grass show on the other side of the trunk</td>', 'the framing seems a little odd, I would have liked to see more of the tree in the foreground, pulling back from the scene a bit and letting grass show on the other side of the trunk', '2002-04-24 13:29:00.000000', NULL, 1),
(53704, 1168, 789, '<td valign="top">Love the use of the foreground. Well done.</td>', 'Love the use of the foreground. Well done.', '2002-04-25 22:28:00.000000', NULL, 1),
