(53706, 1168, 888, '<td valign="top">From small acorns mighty oaks grow.<br/>Technically not oaks but you know what I mean)</td>', 'From small acorns mighty oaks grow.Technically not oaks but you know what I mean)', '2002-04-27 12:05:00.000000', NULL, 1),
(53707, 1168, 811, '<td valign="top">At first, I didn''t like the way this shot was framed, but the more I look at it, the more I like it.</td>', 'At first, I didn''t like the way this shot was framed, but the more I look at it, the more I like it.', '2002-04-27 12:47:00.000000', NULL, 1),
(53708, 1168, 1290, '<td valign="top">Don''t understand the title, but it is a beautiful, peaceful place you have photographed.</td>', 'Don''t understand the title, but it is a beautiful, peaceful place you have photographed.', '2002-04-27 21:50:00.000000', NULL, 1),
(53709, 1168, 346, '<td valign="top">I am not sure if you played around with levels or not, but the green seems almost too green.</td>', 'I am not sure if you played around with levels or not, but the green seems almost too green.', '2002-04-28 07:26:00.000000', NULL, 1),
(53710, 1168, 1181, '<td valign="top">I''m really shocked how many folks don''t get the picture/title/transition, even with the details-comment. The tree on the right has been burned. Next to the burned tree, we have a young sapling - the arboreal equivalent of, say, an elderly person holding their newborn great-grandchild. I like it.</td>', 'I''m really shocked how many folks don''t get the picture/title/transition, even with the details-comment. The tree on the right has been burned. Next to the burned tree, we have a young sapling - the arboreal equivalent of, say, an elderly person holding their newborn great-grandchild. I like it.', '2002-04-29 13:17:00.000000', NULL, 0),
(53711, 1169, 843, '<td valign="top">Pretty good overall. I find the background a bit distracting however as it runs right through the tree.</td>', 'Pretty good overall. I find the background a bit distracting however as it runs right through the tree.', '2002-04-22 02:27:00.000000', NULL, 1),
