(53714, 1169, 933, '<td valign="top">Good colors &amp; composition.</td>', 'Good colors & composition.', '2002-04-25 14:13:00.000000', NULL, 1),
(53715, 1169, 1, '<td valign="top">Nice rich colors.  Good framing of a newly planted tree and a old-timer.</td>', 'Nice rich colors.  Good framing of a newly planted tree and a old-timer.', '2002-04-22 08:24:00.000000', NULL, 1),
