(53775, 1171, 2, '<td valign="top">One of my favorite photos so far.  Great colors, excellent composition, and awesome idea.  Nicely done.</td>', 'One of my favorite photos so far.  Great colors, excellent composition, and awesome idea.  Nicely done.', '2002-04-28 12:39:00.000000', NULL, 1),
