(53777, 1172, 843, '<td valign="top">16 grams of fat! Maybe you should have taken a pic of your gut growing! Kidding aside, nice idea and well executed.</td>', '16 grams of fat! Maybe you should have taken a pic of your gut growing! Kidding aside, nice idea and well executed.', '2002-04-22 03:32:00.000000', NULL, 1),
(53778, 1172, 1078, '<td valign="top">nice idea, but it''s dark -- the knife looks like a piece of black plastic -- not tableware  (although, maybe it is a picnic knife, I don''t know)</td>', 'nice idea, but it''s dark -- the knife looks like a piece of black plastic -- not tableware  (although, maybe it is a picnic knife, I don''t know)', '2002-04-23 14:24:00.000000', NULL, 1),
